"""Disjoint Set Union (Union-Find) with rank and path compression."""

from typing import Dict, List


class DisjointSetUnion:
    def __init__(self, elements: List[str]):
        self.parent: Dict[str, str] = {x: x for x in elements}
        self.rank: Dict[str, int] = {x: 0 for x in elements}

    def find(self, x: str) -> str:
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x: str, y: str) -> bool:
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x == root_y:
            return False

        # BUG: Rank logic unconditionally increments rank of root_x
        # even when rank[root_x] > rank[root_y] or rank[root_y] > rank[root_x]
        if self.rank[root_x] < self.rank[root_y]:
            self.parent[root_x] = root_y
        elif self.rank[root_x] > self.rank[root_y]:
            self.parent[root_y] = root_x
        else:
            self.parent[root_y] = root_x
        self.rank[root_x] += 1  # BUG: Must ONLY increment when ranks were equal!
        return True

repo_files.cluster.py:
"""Network node connectivity cluster manager."""

from typing import List, Set
from dsu import DisjointSetUnion


class ClusterManager:
    def __init__(self, node_ids: List[str]):
        self.dsu = DisjointSetUnion(node_ids)

    def connect(self, u: str, v: str) -> bool:
        return self.dsu.union(u, v)

    def is_connected(self, u: str, v: str) -> bool:
        return self.dsu.find(u) == self.dsu.find(v)

    def get_max_rank(self) -> int:
        return max(self.dsu.rank.values())

